#include <stdio.h>

void swap(int *pa, int *pb)
{
    int tmp = *pa;
    *pa = *pb;
    *pb = tmp;
}


#include <assert.h>
int main(void) {
{ int a=3, b=8; swap(&a,&b); assert(a==8 && b==3); swap(&a,&b); assert(a==3 && b==8); }
{ int a=8, b=3; swap(&a,&b); assert(a==3 && b==8); swap(&a,&b); assert(a==8 && b==3); }
{ int a=5, b=5; swap(&a,&b); assert(a==5 && b==5); swap(&a,&b); assert(a==5 && b==5); }
{ int a=-2, b=-7; swap(&a,&b); assert(a==-7 && b==-2); swap(&a,&b); assert(a==-2 && b==-7); }
{ int a=0, b=0; swap(&a,&b); assert(a==0 && b==0); swap(&a,&b); assert(a==0 && b==0); }
{ int a=-2147483648, b=2147483647; swap(&a,&b); assert(a==2147483647 && b==-2147483648); swap(&a,&b); assert(a==-2147483648 && b==2147483647); }
{ int a=-7; swap(&a,&a); assert(a==-7); }
return 0;
}

