#include <stdio.h>

void suma_roznica(int x, int y, int *ps, int *pr)
{
    *ps = x + y;
    *pr = x - y;
}


#include <assert.h>
int main(void) {
{ int s=99, r=99; suma_roznica(8,3,&s,&r); assert(s==11 && r==5); }
{ int s=99, r=99; suma_roznica(3,8,&s,&r); assert(s==11 && r==-5); }
{ int s=99, r=99; suma_roznica(0,0,&s,&r); assert(s==0 && r==0); }
{ int s=99, r=99; suma_roznica(-3,-8,&s,&r); assert(s==-11 && r==5); }
{ int s=99, r=99; suma_roznica(-8,-3,&s,&r); assert(s==-11 && r==-5); }
{ int s=99, r=99; suma_roznica(-10,7,&s,&r); assert(s==-3 && r==-17); }
return 0;
}

